    public static class AndroidSmokeBuild
    {
        private const string ScenePath = "Assets/_GrindHero/Scenes/FirstSlice.unity";
        private const string SmokeApplicationId = "com.grindhero.smoke";

        [MenuItem("GrindHero/Build Android Smoke APK")]
        public static void Build()
        {
            if (!BuildPipeline.IsBuildTargetSupported(
                    BuildTargetGroup.Android, BuildTarget.Android))
            {
                throw new BuildFailedException(
                    "Install Android Build Support, SDK/NDK tools, and OpenJDK for the pinned Editor.");
            }

            if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.Android)
            {
                throw new BuildFailedException(
                    "Switch to Android in Build Profiles, or launch Unity with -buildTarget Android.");
            }

            if (!File.Exists(ScenePath) || !IsSceneEnabled())
            {
                throw new BuildFailedException(
                    "The first-slice scene must exist and be enabled in Build Profiles.");
            }

            if (PlayerSettings.Android.useCustomKeystore)
            {
                throw new BuildFailedException(
                    "Smoke builds require default Android debug signing, not a custom keystore.");
            }

            var target = NamedBuildTarget.Android;
            var originalIdentifier = PlayerSettings.GetApplicationIdentifier(target);
            var originalBackend = PlayerSettings.GetScriptingBackend(target);
            var originalArchitectures = PlayerSettings.Android.targetArchitectures;
            var originalBundle = EditorUserBuildSettings.buildAppBundle;
            var originalExport = EditorUserBuildSettings.exportAsGoogleAndroidProject;
            var repositoryRoot = Directory.GetParent(Application.dataPath).Parent.FullName;
            var outputDirectory = Path.Combine(repositoryRoot, ".artifacts", "android");
            var outputPath = Path.Combine(outputDirectory, "GrindHero-smoke.apk");
            Directory.CreateDirectory(outputDirectory);

            try
            {
                // Keep the development-only identity separate from future store applications.
                PlayerSettings.SetApplicationIdentifier(target, SmokeApplicationId);
                PlayerSettings.SetScriptingBackend(target, ScriptingImplementation.IL2CPP);
                PlayerSettings.Android.targetArchitectures = AndroidArchitecture.ARM64;
                EditorUserBuildSettings.buildAppBundle = false;
                EditorUserBuildSettings.exportAsGoogleAndroidProject = false;

                var report = BuildPipeline.BuildPlayer(new BuildPlayerOptions
                {
                    scenes = new[] { ScenePath },
                    locationPathName = outputPath,
                    target = BuildTarget.Android,
                    options = BuildOptions.Development
